import {libraryRequest,saveAssetDialog,applyURL,notifyLibraryChanged} from './library-client.js';
const $=id=>document.getElementById(id),uuid=/^[a-f\d-]{36}$/i;
let assets=[],selected=null,viewB=false,zoom=false,loading=false,uploading=false,updating=false,deleting=false,openRevision=0,searchTimer;
function status(message,error=false){$('alStatus').textContent=message;$('alStatus').dataset.error=String(error);}
function safeImage(asset,face='A',thumbnail=false){const expected='/api/library/assets/'+asset.id+(thumbnail?'/thumbnail':face==='B'?'/imageB':'/image'),provided=thumbnail?asset.thumbnailUrl:face==='B'?asset.imageBUrl:asset.imageUrl;return provided===expected?provided:expected;}
function matches(asset){const search=$('alSearch').value.trim().toLocaleLowerCase(),kind=$('alKind').value,series=$('alCollection').value;return(kind==='all'||asset.kind===kind)&&(series==='all'||asset.collection===series)&&(!search||[asset.name,asset.code,asset.collection,asset.description,...asset.tags||[]].join(' ').toLocaleLowerCase().includes(search));}
function render(){const host=$('alGrid'),filtered=assets.filter(matches);host.replaceChildren();$('alCount').textContent=filtered.length===assets.length?'共 '+assets.length+' 张素材':'显示 '+filtered.length+' / '+assets.length+' 张';$('alEmpty').hidden=!!filtered.length;$('alEmpty').querySelector('h2').textContent=assets.length?'没有找到符合条件的图片。':'从一张喜欢的花稿开始。';for(const asset of filtered){const card=document.createElement('article');card.className='al-card';card.dataset.assetId=asset.id;const preview=document.createElement('button');preview.type='button';preview.className='al-card-preview';preview.setAttribute('aria-label','预览 '+asset.name);preview.onclick=()=>void openAsset(asset.id);const image=document.createElement('img');image.src=safeImage(asset,'A',true);image.alt=asset.name;image.loading='lazy';const badge=document.createElement('span');badge.className='al-card-badge';badge.textContent=(asset.kind==='product'?'商品':'花型')+(asset.hasB?' · 双面':'');preview.append(image,badge);const info=document.createElement('div');info.className='al-card-info';const name=document.createElement('h2');name.textContent=asset.name;const subtitle=document.createElement('p');subtitle.className='al-card-subtitle';subtitle.textContent=[asset.code,asset.collection].filter(Boolean).join(' · ')||'可用于下一次创作';const size=document.createElement('div');size.className='al-card-size';size.textContent=asset.width+' × '+asset.height+' px'+(asset.print?.dpi?' · '+asset.print.dpi+' DPI':'');const links=document.createElement('div');links.className='al-card-links';for(const [label,side]of [['用作 A 面','A'],['用作 B 面','B'],...(asset.kind==='product'?[['应用整款','pair']]:[])]){const link=document.createElement('a');link.href=applyURL(asset.id,side);link.textContent=label;links.append(link);}info.append(name,subtitle,size,links);card.append(preview,info);host.append(card);}}
function collections(){const value=$('alCollection').value;$('alCollection').replaceChildren(new Option('全部系列','all'));for(const collection of [...new Set(assets.map(asset=>asset.collection).filter(Boolean))].sort((a,b)=>a.localeCompare(b,'zh-CN')))$('alCollection').append(new Option(collection,collection));if([...$('alCollection').options].some(option=>option.value===value))$('alCollection').value=value;}
async function refresh(){if(loading)return;loading=true;$('alRefresh').disabled=true;try{const data=await libraryRequest();if(!Array.isArray(data.assets))throw Error('图库列表暂时无法读取');assets=data.assets.filter(asset=>asset&&uuid.test(asset.id));collections();render();status('主动保存，仅整理图片，不调用 AI。');}catch(error){status(error.message,true);}finally{loading=false;$('alRefresh').disabled=false;}}
function renderImage(){if(!selected)return;const url=safeImage(selected,viewB?'B':'A');if($('alPreviewImage').getAttribute('src')!==url)$('alPreviewImage').src=url;$('alPreviewImage').alt=selected.name+(viewB?' · B 面':' · A 面 / 主图');$('alViewA').setAttribute('aria-pressed',String(!viewB));$('alViewB').setAttribute('aria-pressed',String(viewB));$('alZoom').setAttribute('aria-pressed',String(zoom));$('alZoom').textContent=zoom?'适应预览':'100% 检查';$('alImageView').classList.toggle('is-zoom',zoom);$('alImageSize').textContent=(viewB?selected.widthB:selected.width)+' × '+(viewB?selected.heightB:selected.height)+' px';}
function fillDetails(){if(!selected)return;$('alPreviewName').textContent=selected.name;const fields={alName:selected.name,alCode:selected.code||'',alSeries:selected.collection||'',alEditKind:selected.kind,alTags:(selected.tags||[]).join('，'),alDescription:selected.description||''};for(const [id,value]of Object.entries(fields))$(id).value=value;$('alEditKind').disabled=!!selected.recipe;$('alViewB').hidden=!selected.hasB;$('alDownload').href=safeImage(selected);$('alDownload').download=selected.name+'.png';$('alDownloadB').hidden=!selected.hasB;if(selected.hasB){$('alDownloadB').href=safeImage(selected,'B');$('alDownloadB').download=selected.name+'_B面.png';}$('alApplyA').href=applyURL(selected.id,'A');$('alApplyB').href=applyURL(selected.id,'B');$('alApplyPair').hidden=selected.kind!=='product';$('alApplyPair').href=applyURL(selected.id,'pair');$('alPrintInfo').textContent=selected.print?'花稿规格 '+selected.print.widthCm+' × '+selected.print.heightCm+' cm · '+selected.print.dpi+' DPI。用于设计参考，生产前仍需打样确认。':'按入库的原始像素下载，图库不做放大或 AI 重绘。';$('alSourceInfo').textContent=[selected.source?'来自 '+selected.source:'',selected.recipe?'整款商品含已保存的产品与工艺设置，可通过“应用整款商品”恢复。':'',selected.hasB?'已保留独立 A / B 面图片。':''].filter(Boolean).join(' ');renderImage();}
async function openAsset(id){const revision=++openRevision;status('正在打开图片…');try{const result=await libraryRequest('/'+id);if(revision!==openRevision)return;if(!result.asset||!uuid.test(result.asset.id))throw Error('这张图片暂时无法读取');selected=result.asset;viewB=zoom=false;fillDetails();$('alPreviewStatus').textContent='';if(!$('alPreview').open)$('alPreview').showModal();const url=new URL(location.href);url.searchParams.set('asset',id);history.replaceState(history.state,'',url.pathname+url.search);status('图片已打开，可查看原稿或继续用于拍摄。');}catch(error){status(error.message,true);}}
$('alSearch').oninput=()=>{clearTimeout(searchTimer);searchTimer=setTimeout(render,150);};$('alKind').onchange=$('alCollection').onchange=render;$('alRefresh').onclick=refresh;
function pick(){$('alFile').click();}$('alUpload').onclick=$('alEmptyUpload').onclick=pick;$('alFile').onchange=async event=>{const file=event.target.files[0];event.target.value='';if(!file||uploading)return;uploading=true;$('alUpload').disabled=$('alEmptyUpload').disabled=true;try{const asset=await saveAssetDialog({blob:file,name:file.name.replace(/\.[^.]+$/,''),source:'图库主动上传',kind:'pattern'});if(asset){await refresh();await openAsset(asset.id);}}catch(error){status(error.message,true);}finally{uploading=false;$('alUpload').disabled=$('alEmptyUpload').disabled=false;}};
$('alClose').onclick=()=>{if(!updating&&!deleting)$('alPreview').close();};$('alPreview').addEventListener('cancel',event=>{if(updating||deleting)event.preventDefault();});$('alPreview').addEventListener('close',()=>{openRevision++;const url=new URL(location.href);url.searchParams.delete('asset');history.replaceState(history.state,'',url.pathname+url.search);});$('alViewA').onclick=()=>{viewB=false;renderImage();};$('alViewB').onclick=()=>{if(!selected?.hasB)return;viewB=true;renderImage();};$('alZoom').onclick=()=>{zoom=!zoom;renderImage();};$('alPreviewImage').onerror=()=>$('alPreviewStatus').textContent='原图暂时无法读取，请关闭后刷新图库重试。';
$('alEditForm').onsubmit=async event=>{event.preventDefault();if(!selected||updating)return;const id=selected.id,tags=$('alTags').value.split(/[,，、]/).map(tag=>tag.trim()).filter(Boolean);if(tags.length>20||tags.some(tag=>tag.length>40))return $('alPreviewStatus').textContent='标签最多 20 项，每项不超过 40 字。';const input={name:$('alName').value.trim(),code:$('alCode').value.trim(),collection:$('alSeries').value.trim(),kind:$('alEditKind').value,tags,description:$('alDescription').value.trim()};updating=true;$('alUpdate').disabled=$('alClose').disabled=$('alDelete').disabled=true;try{const result=await libraryRequest('/'+id+'/update',input);if(!result.asset)throw Error('资料更新结果尚未确认，请刷新图库检查');assets=assets.map(asset=>asset.id===id?result.asset:asset);if(selected?.id===id){selected=result.asset;fillDetails();$('alPreviewStatus').textContent='资料已保存，原图没有修改。';}notifyLibraryChanged();collections();render();}catch(error){$('alPreviewStatus').textContent=error.message;}finally{updating=false;$('alUpdate').disabled=$('alClose').disabled=$('alDelete').disabled=false;}};
$('alDelete').onclick=()=>{if(!selected||updating||deleting)return;$('alDeleteName').textContent=selected.name;$('alDeleteDialog').showModal();};$('alDeleteDialog').addEventListener('close',async()=>{if($('alDeleteDialog').returnValue!=='delete'||!selected||deleting)return;const id=selected.id;deleting=true;try{await libraryRequest('/'+id+'/delete',{});assets=assets.filter(asset=>asset.id!==id);if(selected?.id===id){selected=null;$('alPreview').close();}notifyLibraryChanged();collections();render();status('已从图库移除。');}catch(error){$('alPreviewStatus').textContent=error.message;}finally{deleting=false;}});
window.addEventListener('storage',event=>{if(event.key==='zhijing-library-updated-v1')void refresh();});window.addEventListener('focus',()=>{if(!document.querySelector('.lib-save-dialog[open]'))void refresh();});await refresh();const requested=new URL(location.href).searchParams.get('asset');if(uuid.test(requested||''))void openAsset(requested);
